// App module. UniFFI integration choice (may-decide, §13): bindings are
// generated by the `uniffi-bindgen` CLI from the host-built Rust library
// (`--library` mode), and the Rust cross-compiles run through `cargo-ndk`.
// Both are plain Exec tasks below; see README.md for the exact host setup.

import groovy.json.JsonSlurper
import org.gradle.api.tasks.Exec

plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
    id("org.jetbrains.kotlin.plugin.compose")
}

val repoDir = rootDir.resolve(findProperty("trollm.repoDir") as String? ?: "../..")
    .canonicalFile
// Cargo owns the product version and the separate Android release counter.
// Reading workspace metadata does not fetch or compile dependencies.
val cargoMetadata = JsonSlurper().parseText(providers.exec {
    workingDir(repoDir)
    commandLine("cargo", "metadata", "--format-version", "1", "--no-deps", "--offline", "--locked")
}.standardOutput.asText.get()) as Map<*, *>
val productVersions = (cargoMetadata["packages"] as List<*>)
    .map { (it as Map<*, *>)["version"] as String }.distinct()
require(productVersions.size == 1) { "Workspace crates must share one product version" }
val productVersion = productVersions.single()
val androidVersionCode = ((cargoMetadata["metadata"] as Map<*, *>)["android"] as Map<*, *>)["version-code"]
    .let { it as? Int ?: error("workspace.metadata.android.version-code must be an integer") }
require(androidVersionCode in 1..2_100_000_000) {
    "workspace.metadata.android.version-code must be in 1..2100000000"
}
val rustFeatures = findProperty("trollm.rustFeatures") as String? ?: "llama"
require(rustFeatures == "stub" || rustFeatures == "llama") {
    "trollm.rustFeatures must be stub or llama"
}
val androidTargets = linkedMapOf(
    "arm64-v8a" to "aarch64-linux-android",
    "armeabi-v7a" to "arm-linux-androideabi",
    "x86_64" to "x86_64-linux-android",
)
val androidAbis = (findProperty("trollm.androidAbis") as String?
    ?: androidTargets.keys.joinToString(","))
    .split(',').map(String::trim).filter(String::isNotEmpty).distinct()
require(androidAbis.isNotEmpty() && androidAbis.all(androidTargets::containsKey)) {
    "trollm.androidAbis contains an unsupported ABI"
}
// Cargo metadata resolves config and relative CARGO_TARGET_DIR values from
// repoDir, exactly as the build/generation commands below do.
val cargoTargetDir = file(cargoMetadata["target_directory"] as String)
val hostLibraryName = when {
    System.getProperty("os.name").startsWith("Windows", ignoreCase = true) ->
        "trollm_uniffi.dll"
    System.getProperty("os.name").startsWith("Mac", ignoreCase = true) ->
        "libtrollm_uniffi.dylib"
    else -> "libtrollm_uniffi.so"
}
val jniLibsDir = layout.projectDirectory.dir("src/main/jniLibs")
val uniffiGenDir = layout.buildDirectory.dir("generated/uniffi")

// Release signing is explicit and independent of the developer debug key.
val releaseSigning = listOf(
    "TROLLM_RELEASE_KEYSTORE_PATH", "TROLLM_RELEASE_KEY_ALIAS",
    "TROLLM_RELEASE_STORE_PASSWORD", "TROLLM_RELEASE_KEY_PASSWORD",
).associateWith { System.getenv(it) }
val releaseSigningComplete = releaseSigning.values.all { !it.isNullOrBlank() }
val releaseSigningMessage = "Release builds require all TROLLM_RELEASE signing inputs: " +
    releaseSigning.keys.joinToString(", ")

val sourceRevision = System.getenv("TROLLM_SOURCE_REVISION") ?: providers.exec {
    workingDir(repoDir)
    commandLine("git", "rev-parse", "HEAD")
}.standardOutput.asText.get().trim()
require(sourceRevision.matches(Regex("[a-f0-9]{40}"))) { "Exact source revision is required" }

android {
    namespace = "com.trollm.app"
    ndkVersion = "27.2.12479018"
    compileSdk = 35

    defaultConfig {
        applicationId = "com.trollm.app"
        minSdk = 33 // UniFFI's generated JVM Cleaner bindings require Android 13.
        targetSdk = 35
        versionCode = androidVersionCode
        versionName = productVersion
        buildConfigField("String", "SOURCE_REVISION", "\"$sourceRevision\"")
        ndk {
            abiFilters += androidAbis
        }
    }

    System.getenv("TROLLM_DEBUG_KEYSTORE_PATH")?.let { path ->
        signingConfigs.getByName("debug") {
            storeFile = file(path)
            storePassword = "android"
            keyAlias = "androiddebugkey"
            keyPassword = "android"
        }
    }

    if (releaseSigningComplete) {
        signingConfigs.create("projectRelease") {
            storeFile = file(releaseSigning.getValue("TROLLM_RELEASE_KEYSTORE_PATH")!!)
            storePassword = releaseSigning.getValue("TROLLM_RELEASE_STORE_PASSWORD")
            keyAlias = releaseSigning.getValue("TROLLM_RELEASE_KEY_ALIAS")
            keyPassword = releaseSigning.getValue("TROLLM_RELEASE_KEY_PASSWORD")
        }
        buildTypes.getByName("release") {
            signingConfig = signingConfigs.getByName("projectRelease")
        }
    }
    buildTypes.getByName("release") { isDebuggable = false }

    if ((findProperty("trollm.androidBuildType") as String? ?: "debug") == "release" ||
        gradle.startParameter.taskNames.any { it.substringAfterLast(':') in setOf("assembleRelease", "bundleRelease", "packageRelease") }) {
        require(releaseSigningComplete) { releaseSigningMessage }
    }

    buildFeatures {
        buildConfig = true
        compose = true
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    sourceSets {
        getByName("test") {
            // Shared Rust/JVM identity cases also work in the curated export without .git.
            resources.srcDir(repoDir.resolve("crates/trollm-uniffi/tests/fixtures"))
        }
        getByName("main") {
            assets.srcDir(layout.buildDirectory.dir("generated/third-party-notices/assets"))
            // cargo-ndk writes libtrollm_uniffi.so per ABI here.
            jniLibs.srcDir(jniLibsDir)
            // uniffi-bindgen Kotlin output.
            java.srcDir(uniffiGenDir)
        }
    }
}

// Aggregate tasks (for example `assemble`) must not emit an unsigned release.
tasks.matching { it.name == "packageRelease" || it.name == "packageReleaseBundle" }.configureEach {
    doFirst {
        check(releaseSigningComplete) { releaseSigningMessage }
    }
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
    }
}

// --- Rust + UniFFI wiring ---------------------------------------------------

// Host build of the cdylib: uniffi-bindgen --library reads the UniFFI
// metadata embedded in any build of the crate; the host build is cheapest.
val buildRustHost = tasks.register<Exec>("buildRustHost") {
    workingDir = repoDir
    commandLine("cargo", "build", "--locked", "-p", "trollm-uniffi")
}

// Cross-compile for the requested supported ABIs. cargo-ndk places
// libtrollm_uniffi.so under <jniLibs>/<abi>/.
val buildRustAndroid = tasks.register<Exec>("buildRustAndroid") {
    workingDir = repoDir
    commandLine(buildList {
        addAll(listOf(
            "cargo", "ndk",
            "--platform", (android.defaultConfig.minSdk
                ?: error("Android minSdk is required for the Rust build")).toString(),
        ))
        androidAbis.forEach { abi -> addAll(listOf("-t", abi)) }
        addAll(listOf(
            "-o", jniLibsDir.asFile.absolutePath,
            "build", "--locked", "-p", "trollm-uniffi", "--release", "--features", rustFeatures,
        ))
    })
    if (rustFeatures == "llama") {
        environment("CMAKE_BUILD_PARALLEL_LEVEL", System.getenv("CMAKE_BUILD_PARALLEL_LEVEL")?.takeIf(String::isNotBlank) ?: "2")
        doLast {
            val ndk = file(System.getenv("ANDROID_NDK_HOME")
                ?: error("ANDROID_NDK_HOME is required to package libc++_shared.so"))
            val toolchain = ndk.resolve("toolchains/llvm/prebuilt").listFiles()
                ?.singleOrNull { it.isDirectory }
                ?: error("Expected one NDK host toolchain")
            for (abi in androidAbis) {
                val target = androidTargets.getValue(abi)
                val runtime = toolchain.resolve("sysroot/usr/lib/$target/libc++_shared.so")
                check(runtime.isFile) { "Missing NDK C++ runtime for $abi" }
                copy {
                    from(runtime)
                    into(jniLibsDir.dir(abi))
                }
            }
        }
    }
}

// Generate the Kotlin bindings into build/generated/uniffi. Uses the local
// `uniffi-bindgen` shim binary in crates/trollm-uniffi (UniFFI 0.28 ships
// no installable CLI crate), which pins generation to the exact UniFFI
// version the crate compiles against.
val generateUniFFIBindings = tasks.register<Exec>("generateUniFFIBindings") {
    dependsOn(buildRustHost)
    workingDir = repoDir
    commandLine(
        "cargo", "run", "--locked", "-q",
        "-p", "trollm-uniffi",
        "--bin", "uniffi-bindgen",
        "--features", "bindgen-cli",
        "--",
        "generate", "--metadata-no-deps", "--no-format",
        "--library", cargoTargetDir.resolve("debug/$hostLibraryName").absolutePath,
        "--language", "kotlin",
        "--out-dir", uniffiGenDir.get().asFile.absolutePath,
    )
}

tasks.named("preBuild") {
    dependsOn(buildRustAndroid, generateUniFFIBindings)
}

dependencies {
    testImplementation("junit:junit:4.13.2")
    testImplementation("org.json:json:20250517")
    implementation("net.openid:appauth:0.11.1")
    // UniFFI 0.28 Kotlin requires JNA >= 5.12.0; Android needs the AAR.
    implementation("net.java.dev.jna:jna:5.14.0@aar")
    val composeBom = platform("androidx.compose:compose-bom:2025.04.01")
    implementation(composeBom)
    implementation("androidx.core:core-ktx:1.16.0")
    implementation("androidx.activity:activity-compose:1.10.1")
    implementation("androidx.lifecycle:lifecycle-runtime-compose:2.8.7")
    implementation("androidx.compose.ui:ui")
    implementation("androidx.compose.material3:material3")
    implementation("androidx.compose.ui:ui-tooling-preview")
    debugImplementation("androidx.compose.ui:ui-tooling")
    // Keystore-backed token storage (§10).
    implementation("androidx.security:security-crypto:1.1.0-alpha07")
}
